"""Build the three bilingual static pages. No frontend build/runtime dependency."""
from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def t(pt, en, tag="span", attrs=""):
    return f'<{tag} data-pt="{escape(pt, quote=True)}" data-en="{escape(en, quote=True)}" {attrs}>{escape(pt)}</{tag}>'


def icon(name="arrow-right", base=""):
    return f'<svg aria-hidden="true"><use href="{base}assets/icons.svg#{name}"/></svg>'


def button(pt, en, href, base="", outline=False):
    return f'<a class="button{" outline" if outline else ""}" href="{href}">{t(pt,en)}{icon(base=base)}</a>'


def link(pt, en, href, base=""):
    return f'<a class="text-link" href="{href}">{t(pt,en)}{icon("arrow-up-right",base)}</a>'


def details(pt, en, body_pt, body_en):
    return f'<details>{t(pt,en,"summary")}{t(body_pt,body_en,"p")}</details>'


def page(title, desc, main, script, base=""):
    return f'''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — Gabriel Costa</title><meta name="description" content="{escape(desc,quote=True)}"><meta property="og:title" content="{title} — Gabriel Costa"><meta property="og:description" content="Good decisions. Reliable data. Explore the analysis and inspect the engineering."><meta property="og:image" content="https://gabrielcosta06.github.io/portfolio-data-analyst/assets/social.png"><meta property="og:type" content="website"><meta name="theme-color" content="#153d32"><link rel="icon" href="{base}assets/favicon.svg"><link rel="stylesheet" href="{base}assets/portfolio.css"><script type="module" src="{script}"></script></head>
<body><a class="skip" href="#main">{t("Pular para o conteúdo","Skip to content")}</a><div class="shell"><header class="masthead"><a class="wordmark" href="{base or './'}">Gabriel Costa</a><nav class="nav" aria-label="Principal / Main"><a href="{base}#projetos">{t("Projetos","Work")}</a><a href="{base}#sobre">{t("Sobre","About")}</a><div class="languages" role="group" aria-label="Idioma / Language"><button data-lang="pt" aria-pressed="true" aria-label="Português">PT</button><button data-lang="en" aria-pressed="false" aria-label="English">EN</button></div></nav></header><main id="main">{main}</main><footer class="footer">{t("Feito para explorar. Construído para verificar.","Made to explore. Built to verify.","p")}<nav aria-label="Links"><a href="https://github.com/GabrielCosta06">GitHub</a><a href="https://www.linkedin.com/in/josegabriel-costa/">LinkedIn</a><a href="{base}projects/pipeline/">Spark / Delta</a><a href="{base}start/">{t("Guia de execução","Execution guide")}</a></nav></footer></div><noscript><p class="noscript">JavaScript is required for interactive charts. <a href="{base}docs/commercial.md">Case documentation</a> · <a href="{base}data/commercial/demo-evidence.json">JSON evidence</a></p></noscript></body></html>'''


def chart_header():
    return f'<div class="chart-header"><div>{t("Receita e margem","Revenue and margin","h3")}{t("Caso comercial · jan–out 2026 · dados sintéticos","Commercial case · Jan–Oct 2026 · synthetic data","p")}</div></div>'


def legend():
    return f'<div class="chart-legend"><span><i class="legend-key"></i>{t("Receita líquida","Net revenue")}</span><span><i class="legend-key gold"></i>{t("Margem bruta","Gross margin")}</span></div>'


def flow(engineering=False):
    steps = [
        ("INPUT", "Origem", "Source", "Eventos versionados, clientes e produtos.", "Versioned events, customers and products."),
        ("CONTRACT", "Validação", "Validation", "Contrato, referências e quarentena rastreável.", "Contracts, references and traceable quarantine."),
        ("STATE", "Warehouse", "Warehouse", "Atualizações incrementais e publicação atômica.", "Incremental updates and atomic publication."),
        ("DECISION", "Análise", "Analysis", "Indicadores reconciliados, hipóteses e cenários.", "Reconciled metrics, hypotheses and scenarios.")]
    return '<div class="flow">' + ''.join(f'<div class="flow-step"><span class="mono">0{i} / {s[0]}</span>{t(s[1],s[2],"h3")}{t(s[3],s[4],"p")}</div>' for i,s in enumerate(steps,1)) + '</div>'


def home():
    paths = ''
    for name, pt, en, subpt, suben, target in [
        ("bar-chart","Explorar a análise","Explore the analysis","Indicadores, causas e decisões","Metrics, drivers and decisions","analysis"),
        ("database","Inspecionar a engenharia","Inspect the engineering","Ingestão, correções, testes e recuperação","Ingestion, corrections, tests and recovery","engineering")]:
        paths += f'<a class="path" href="projects/commercial/#{target}"><span class="path-icon">{icon(name)}</span><span>{t(pt,en,"strong")}{t(subpt,suben,"small")}</span>{icon()}</a>'
    main = f'''
<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><h1 id="hero-title">{t("Decisões claras.","Good decisions.")}<br>{t("Dados confiáveis.","Reliable data.","em")}</h1>{t("Análise de dados e engenharia, do problema de negócio à construção de uma base em que você pode confiar.","Data analysis and engineering, from the business question to a foundation you can trust.","p")}<div class="actions">{button("Explorar a análise","Explore the analysis","projects/commercial/#analysis")}{button("Inspecionar a engenharia","Inspect the engineering","projects/commercial/#engineering",outline=True)}</div><p class="hero-note mono">SQL · Python · Power BI · PySpark · Delta Lake</p></div><div class="chart-surface hero-chart">{chart_header()}{legend()}<div id="hero-chart" class="chart" role="img" aria-label="Monthly revenue and gross margin"></div><div class="chart-caption">{t("Receita maior. Margem menor. Por quê?","More revenue. Less margin. Why?")}<a href="projects/commercial/#analysis">{t("Investigar","Investigate")}</a></div></div></section>
<section class="feature" id="projetos" aria-labelledby="feature-title"><div class="feature-copy">{t("01 / Projeto principal","01 / Featured project","p",'class="section-index"')}<h2 id="feature-title">Commercial<br>Intelligence</h2>{t("Uma investigação comercial apoiada por um pipeline incremental. Receita, margem, clientes e qualidade dos dados, conectados em um único produto.","A commercial investigation backed by an incremental pipeline. Revenue, margin, customers and data quality, connected in one product.","p")}<div class="paths">{paths}</div></div><div class="workspace-preview"><a href="projects/commercial/#analysis" aria-label="Open Commercial Intelligence"><div class="preview-header"><span>Commercial Intelligence</span>{t("SNAPSHOT REPRODUZÍVEL","REPRODUCIBLE SNAPSHOT","span",'class="mono"')}</div><div class="preview-body"><div class="preview-kpis"><div>{t("Receita líquida","Net revenue","small")}<strong id="preview-revenue">—</strong></div><div>{t("Margem bruta","Gross margin","small")}<strong id="preview-margin">—</strong></div><div>{t("Itens válidos","Valid items","small")}<strong id="preview-items">—</strong></div></div><div class="chart-header"><div>{t("O desempenho por trás do total","The performance behind the total","h3")}{t("Indicadores calculados a partir do pipeline.","Metrics calculated from the pipeline.","p")}</div></div><div id="preview-chart" class="chart" role="img" aria-label="Monthly revenue and margin preview"></div><div class="preview-foot"><span id="preview-evidence">SQL / Python</span><span class="text-link">{t("Abrir workspace","Open workspace")}{icon("arrow-up-right")}</span></div></div></a></div></section>
<section class="evidence-band"><div>{t("A evidência","The evidence","p",'class="section-index"')}{t("Da origem à decisão.","From source to insight.","h2")}{t("Cada resultado tem um caminho verificável até a origem, com código e controles inspecionáveis.","Every result has a traceable path to its source, with inspectable code and controls.","p")}{link("Ver arquitetura e execuções","See architecture and runs","projects/commercial/#engineering")}</div>{flow()}</section>
<section class="secondary-case"><div>{t("02 / Dados públicos","02 / Public data","p",'class="section-index"')}{t("O que entra na conta?","What goes into the number?","h2")}</div><div class="case-description">{t("Como a inclusão de mudanças no uso da terra altera a leitura das emissões de CO₂ do Brasil. Uma investigação independente com dados públicos, fonte versionada e escolhas metodológicas explícitas.","How including land-use change alters the reading of Brazil’s CO₂ emissions. An independent investigation with public data, a versioned source and explicit methodological choices.","p")}{link("Explorar o estudo do Brasil","Explore the Brazil study","projects/brazil/")}</div></section>
<section class="about" id="sobre"><div>{t("A pessoa por trás dos dados","The person behind the data","p",'class="section-index"')}<h2>Gabriel Costa.</h2></div><div>{t("Atuo na conexão entre análise de dados e engenharia. Minha experiência inclui dados de diferentes departamentos e fontes SQL e Progress/TOTVS. Aqui, demonstro como transformo perguntas em análises claras e processos reproduzíveis.","I work at the intersection of data analysis and engineering. My experience includes data across departments and SQL and Progress/TOTVS sources. Here, I demonstrate how I turn questions into clear analysis and reproducible processes.","p")}{t("Projetos desenvolvidos com assistência de IA. Dados comerciais sintéticos, sem informações de empregadores, clientes ou colaboradores. O estudo público identifica sua fonte e seu recorte.","Projects developed with AI assistance. Commercial data is synthetic, with no employer, customer or employee information. The public-data study identifies its source and scope.","p",'class="micro"')}<div class="skills-line"><span>SQL & Python</span><span>Power BI & DAX</span><span>PySpark & Delta Lake</span>{t("Qualidade de dados","Data quality")}</div><div class="resume-row" id="curriculo"><a href="assets/cv/pt/jose_gabriel_cv.pdf" download>Currículo PT · PDF</a><a href="assets/cv/en/jose_gabriel_cv.pdf" download>Résumé EN · PDF</a><a href="assets/cv/pt/jose_gabriel_cv.docx" download>PT · Word</a><a href="assets/cv/en/jose_gabriel_cv.docx" download>EN · Word</a></div></div></section>'''
    return page("Data Analytics & Data Engineering", "Portfólio de Gabriel Costa: análise comercial, engenharia de dados, SQL, Python e Power BI. Explore análises e evidência reproduzível.", main, "assets/home.js")


def table(headers, body_id):
    heads = ''.join(f'<th scope="col" class="{("numeric" if numeric else "")}">{t(pt,en)}</th>' for pt,en,numeric in headers)
    return f'<div class="table-wrap"><table><thead><tr>{heads}</tr></thead><tbody id="{body_id}"></tbody></table></div>'


def panel(pt, en, body, note_pt="", note_en=""):
    return f'<div class="panel">{t(pt,en,"h2")}{t(note_pt,note_en,"p",'class="intro"') if note_pt else ""}{body}</div>'


def commercial():
    b = "../../"
    top = f'<section class="case-top"><div><h1>Commercial Intelligence</h1>{t("Receita maior não garante margem melhor. Investigue o resultado e inspecione o sistema que sustenta cada indicador.","Higher revenue does not guarantee better margin. Investigate the results and inspect the system behind every metric.","p",'class="lede"')}</div><aside class="case-context">{t("Demonstração · jan–out 2026","Demonstration · Jan–Oct 2026","strong")}{t("Dados sintéticos. Não representa resultados de uma empresa. Snapshot, sem conexão com ERP.","Synthetic data. Does not represent company results. A snapshot with no ERP connection.","p")}<a href="../../data/commercial/demo-evidence.json">{t("Inspecionar evidência JSON","Inspect JSON evidence")}</a></aside></section>'
    tabs = '<nav class="tabbar" aria-label="Workspace">' + ''.join(f'<button data-tab="{key}" aria-pressed="{str(i==1).lower()}" aria-controls="{key}"><small>0{i}</small>{t(pt,en)}</button>' for i,(key,pt,en) in enumerate([("analysis","Análise","Analysis"),("quality","Laboratório de qualidade","Quality laboratory"),("engineering","Engenharia","Engineering")],1)) + '</nav>'
    filters = '<div class="filterbar">' + ''.join(f'<label>{t(pt,en)}<select id="{key}">{t(apt,aen,"option",'value=""')}</select></label>' for key,pt,en,apt,aen in [("month","Mês","Month","Todos os meses","All months"),("category","Categoria","Category","Todas as categorias","All categories"),("region","Região","Region","Todas as regiões","All regions"),("channel","Canal","Channel","Todos os canais","All channels")]) + f'<button id="reset" class="small-button">{t("Limpar","Reset")}</button><button id="export" class="small-button">{t("Exportar CSV","Export CSV")}{icon("download",b)}</button></div><p id="filter-status" class="filter-status" role="status" aria-live="polite"></p>'
    kpis = '<div class="kpis">' + ''.join(f'<div class="kpi">{t(pt,en)}<strong id="{key}">—</strong>{t(npt,nen,"small")}</div>' for key,pt,en,npt,nen in [("revenue","Receita líquida","Net revenue","Após descontos e devoluções","After discounts and returns"),("profit","Lucro bruto","Gross profit","Receita líquida − custo direto","Net revenue − direct cost"),("margin","Margem bruta","Gross margin","Ponderada pela receita","Revenue weighted"),("orders","Pedidos","Orders","IDs de pedidos distintos","Distinct order IDs")]) + '</div>'
    revenue_headers = [("Mês","Month",False),("Receita líquida","Net revenue",True),("Margem bruta","Gross margin",True)]
    monthly = panel("Receita e margem","Revenue and margin",legend()+'<div id="monthly-chart" class="chart" role="img" aria-label="Monthly revenue and gross margin"></div><details>'+t("Ver dados do gráfico","View chart data","summary")+table(revenue_headers,"monthly-table")+'</details>',"Meses completos. Eixos independentes; receita começa em zero.","Complete months. Independent axes; revenue starts at zero.")
    findings = panel("O que os números dizem","What the numbers say",'<div id="findings" aria-live="polite"></div>',"Conclusões calculadas para o recorte selecionado.","Findings calculated for the selected slice.")
    categories = panel("Contribuição por categoria","Category contribution",table([("Categoria","Category",False),("Receita líquida","Net revenue",True),("Lucro bruto","Gross profit",True),("Margem","Margin",True)],"category-table"),"Compare receita, lucro bruto e margem ponderada.","Compare revenue, gross profit and weighted margin.")
    bridge = panel("Da venda à receita líquida","From sales to net revenue",'<div id="revenue-bridge" class="bridge"></div>',"Conciliação aditiva: cada desconto e estorno entra uma vez.","An additive reconciliation: each discount and refund enters once.")
    customers = panel("Receita não é contribuição","Revenue is not contribution",table([("Cliente","Customer",False),("Segmento","Segment",False),("Receita líquida","Net revenue",True),("Lucro bruto","Gross profit",True),("Margem","Margin",True),("% da receita","Revenue share",True)],"customer-table"),"Os oito maiores clientes por receita. Lucro bruto antes de custos de atendimento e aquisição.","The eight largest customers by revenue. Gross profit before servicing and acquisition costs.")
    scenario = f'<section class="scenario"><div>{t("E se o desconto mudar?","What if discounts change?","h2")}{t("Aplique um desconto adicional sobre a receita líquida e uma variação no custo direto do recorte. Volume e devoluções permanecem constantes.","Apply an additional discount to net revenue and a change in direct cost for this slice. Volume and returns stay constant.","p")}{t("Cenário aritmético, não previsão. Sem elasticidade, impostos, frete ou mudança no comportamento de compra.","Arithmetic scenario, not a forecast. No elasticity, taxes, freight or changes in buying behavior.","p")}</div><div class="scenario-inputs"><label class="range-label">{t("Desconto adicional","Additional discount")}<output id="discount-value" for="discount">0%</output><input id="discount" type="range" min="0" max="15" step="0.5" value="0"></label><label class="range-label">{t("Variação de custo","Cost change")}<output id="cost-value" for="cost">0%</output><input id="cost" type="range" min="-10" max="20" step="0.5" value="0"></label><div class="scenario-result" aria-live="polite"><div>{t("Margem no cenário","Scenario margin")}<br><strong id="scenario-margin">—</strong></div><div>{t("Variação do lucro bruto","Change in gross profit")}<br><strong id="scenario-delta">—</strong></div></div></div></section>'
    decision = f'<section class="method">{t("Da evidência à decisão.","From evidence to decision.","h2")}<div>{t("A hipótese é que descontos e mix de equipamentos pressionam a margem nos meses finais. Compare categorias e canais antes de propor uma política comercial. A base foi construída para demonstrar o método; não estima um efeito causal real.","The hypothesis is that discounts and equipment mix pressure margin in the final months. Compare categories and channels before proposing a commercial policy. This dataset demonstrates the method; it does not estimate a real causal effect.","p")}{details("Definições, grão e premissas","Definitions, grain and assumptions","Grão: um item ativo de pedido. Pedidos contam IDs distintos. Receita bruta = quantidade × preço de lista. Desconto é arredondado por unidade em centavos. Devoluções estornam receita e custo direto das unidades devolvidas; assume-se recuperação integral do custo. Margem = soma do lucro bruto ÷ soma da receita líquida. Lucro bruto não é lucro líquido.","Grain: one active order item. Orders count distinct IDs. Gross sales = quantity × list price. Discounts are rounded per unit in cents. Returns reverse revenue and direct cost of returned units; full cost recovery is assumed. Margin = total gross profit ÷ total net revenue. Gross profit is not net profit.")}{details("O que esta análise permite concluir","What this analysis can establish","Os filtros descrevem associações. Não há teste A/B ou grupo de controle. Margem pode variar por preço, desconto, custo, devoluções e mix simultaneamente. O simulador mantém as demais variáveis constantes e não modela demanda.","Filters describe associations. There is no A/B test or control group. Margin may change through price, discounts, costs, returns and mix simultaneously. The simulator holds other variables constant and does not model demand.")}<div class="actions"><a class="small-button" href="analysis.sql">SQL</a><a class="small-button" id="full-download" href="../../data/commercial/current.json" download>{t("Baixar base completa","Download full dataset")}</a><a class="small-button" href="../analytics/powerbi/">Power BI companion</a></div></div></section>'
    analysis = f'<section id="analysis" hidden>{filters}{kpis}<div class="analysis-grid">{monthly}{findings}</div><div class="analysis-grid">{categories}{bridge}</div>{customers}{scenario}{decision}</section>'
    labbuttons = ''.join(f'<button class="small-button" data-fault="{key}" aria-pressed="{str(key=="clean").lower()}">{t(pt,en)}</button>' for key,pt,en in [("clean","Amostra limpa","Clean sample"),("duplicate","Duplicar item","Duplicate item"),("cost","Custo negativo","Negative cost"),("customer","Cliente inexistente","Unknown customer")])
    lab = f'<div>{t("Um número errado também pode parecer bom.","A wrong number can look good, too.","h2")}{t("Injete um erro numa amostra de três itens. Compare a soma sem validação com a saída do contrato. O experimento roda no navegador e não altera o snapshot.","Inject an error into a three-item sample. Compare unchecked totals with the contract output. This browser experiment does not change the published snapshot.","p",'class="subtle"')}<div class="lab-controls" role="group" aria-label="Experimento / Experiment">{labbuttons}</div><div class="lab-comparison" aria-live="polite"><div>{t("Lucro sem validação","Unchecked gross profit")}<strong id="unchecked-profit">—</strong></div><div>{t("Lucro após validação","Validated gross profit")}<strong id="validated-profit">—</strong></div></div><p id="lab-message" class="quality-explainer" aria-live="polite"></p><div id="lab-reason" class="lab-reason"></div>{t("Uma linha inválida é isolada, não corrigida automaticamente. A saída pode ficar incompleta; corrija a origem e reprocesse.","An invalid row is isolated, not automatically repaired. Output may be incomplete; correct the source and reprocess.","p",'class="micro"')}</div>'
    qualitypanel = panel("Qualidade do snapshot publicado","Published snapshot quality",'<ul id="quality-counts" class="check-list"></ul>'+table([("Regra","Rule",False),("Ocorrências","Occurrences",True)],"rule-table")+'<div class="actions"><a id="quarantine-download" class="small-button" href="../../data/commercial/current.json" download>'+t("Baixar quarentena","Download quarantine")+'</a></div>',"Contagens de eventos. Uma linha pode acionar várias regras.","Event counts. One row can trigger several rules.")
    quality = '<section id="quality" hidden><div class="lab">'+lab+qualitypanel+'</div><div style="margin-top:24px">'+panel("Rejeições que você pode inspecionar","Rejections you can inspect",'<div class="quality-log">'+table([("event_id","event_id",False),("item_id","item_id",False),("Motivo","Reason",False)],"quarantine-table")+'</div>')+'</div></section>'
    history = panel("Duas execuções. Um replay.","Two runs. One replay.",table([("Execução","Run",False),("Itens válidos","Valid items",True),("Receita líquida","Net revenue",True)],"run-table")+'<ul class="check-list" id="run-checks"></ul>'+t("Histórico reproduzível da demonstração. Não é monitoramento ao vivo ou produção.","Reproducible demo history. Not live monitoring or production.","p",'class="micro"'),"Base inicial → cinco correções, um item atrasado, uma exclusão e um evento antigo → replay.","Baseline → five corrections, one late item, one deletion and one stale event → replay.")
    snapshot = panel("Evidência do snapshot","Snapshot evidence",'<ul class="check-list" id="snapshot-checks"></ul>'+t("Identificador do conteúdo","Content identifier","p",'class="micro"')+'<p class="run-id" id="snapshot-id"></p><a class="text-link" id="manifest-link" href="../../data/commercial/current.json">'+t("Abrir manifesto e hashes","Open manifest and hashes")+'</a>',"Validações executadas pelo pipeline antes da publicação.","Checks executed by the pipeline before publication.")
    failure = f'<section class="method">{t("E quando falha?","What happens on failure?","h2")}<div>{t("O teste injeta uma falha antes da publicação e compara o ponteiro e todos os arquivos anteriores byte a byte. Permanecem intactos. O reprocessamento publica o lote. O leitor resolve o ponteiro uma vez e usa arquivos da mesma execução.","The test injects a failure before publication and compares the pointer and every previous file byte for byte. They remain intact. A retry publishes the batch. Readers resolve the pointer once and use files from the same run.","p")}<pre><code>python src/commercial.py --demo --output .local/demo\npython -m unittest discover -s tests -v\npython -m http.server 8080</code></pre><div class="actions"><a class="small-button" href="../../src/commercial.py">Python</a><a class="small-button" href="../../tests/test_commercial.py">{t("Testes de comportamento","Behavioral tests")}</a><a class="small-button" href="../pipeline/">Spark / Delta</a><a class="small-button" href="../../docs/commercial.md">{t("Decisões técnicas","Technical decisions")}</a></div>{details("Limites de arquitetura","Architecture limits","Pipeline local de um único escritor. Estado em memória; não é CDC de ERP nem serviço distribuído. A troca atômica pressupõe sistema de arquivos local no mesmo volume. GitHub Pages serve artefatos. Produção exigiria agendamento, concorrência distribuída, retenção, autenticação, alertas e testes de carga. Spark/Delta é um estudo complementar com evidência separada; não é o motor deste mart.","Local single-writer pipeline. In-memory state; not ERP CDC or a distributed service. Atomic replacement assumes a local filesystem on one volume. GitHub Pages serves artifacts. Production would require scheduling, distributed concurrency control, retention, authentication, alerts and load testing. Spark/Delta is a companion study with separate evidence; it does not power this mart.")}</div></section>'
    tour = '<section class="panel" id="walkthrough" style="margin-top:24px">'+t("Veja o percurso completo.","Watch the complete walkthrough.","h2")+t("Gravação real da interface, sem áudio. Legendas em português e inglês. Explore análise, cenário, qualidade e engenharia.","Actual interface recording, without audio. Portuguese and English captions. Explore analysis, scenarios, quality and engineering.","p",'class="intro"')+'<video class="walkthrough" controls preload="none" poster="../../assets/walkthrough-poster.png" width="1280" height="800" aria-label="Portfolio walkthrough"><source src="../../assets/walkthrough.webm" type="video/webm"><track kind="captions" src="../../assets/walkthrough.pt.vtt" srclang="pt" label="Português" default><track kind="captions" src="../../assets/walkthrough.en.vtt" srclang="en" label="English">Your browser does not support WebM. <a href="../../assets/walkthrough.webm">Download video</a>.</video></section>'
    engineering = '<section id="engineering" hidden>'+t("O indicador começa antes do gráfico.","The metric starts before the chart.","h2")+t("Eventos versionados entram no contrato; o estado mais recente de cada item produz um mart reconciliado. Leitores acessam um snapshot imutável por um único ponteiro.","Versioned events enter the contract; the latest state of each item produces a reconciled mart. Readers access an immutable snapshot through a single pointer.","p",'class="subtle"')+flow(True)+f'<div class="run-grid">{history}{snapshot}</div>'+tour+failure+'</section>'
    status = '<p id="app-status" class="loading" role="status">'+t("Carregando snapshot verificado…","Loading verified snapshot…")+'</p>'
    return page("Commercial Intelligence", "Análise comercial e engenharia de dados: dashboard, laboratório de qualidade, pipeline incremental e recuperação verificável.",top+tabs+status+analysis+quality+engineering,"commercial.js",b)


def public():
    b = "../../"
    top = '<section class="case-top"><div>'+t("O que entra na conta?","What goes into the number?","h1")+t("Emissões de CO₂ do Brasil: a escolha da fronteira muda a leitura da tendência. Compare valores totais, por pessoa e mudanças desde 2000.","Brazil’s CO₂ emissions: the accounting boundary changes the reading of the trend. Compare totals, per-person values and change since 2000.","p",'class="lede"')+'</div><aside class="case-context">'+t("Dados públicos · 2000–2024","Public data · 2000–2024","strong")+t("Our World in Data / Global Carbon Budget. Snapshot versionado; não é uma série em tempo real.","Our World in Data / Global Carbon Budget. Versioned snapshot, not a live series.","p")+'<a href="../../data/public/source.json">'+t("Fonte e proveniência","Source and provenance")+'</a></aside></section>'
